import{c as n,Q as s,j as t,m as e}from"./chunks/framework.DOi4mjdC.js";const p="/assets/LayerNormGrad%E7%AE%97%E6%B3%95%E6%A1%86%E5%9B%BE.CbS_I72e.png",h=JSON.parse('{"title":"LayerNormGrad","description":"","frontmatter":{},"headers":[{"level":1,"title":"LayerNormGrad","slug":"layernormgrad"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"实现原理","slug":"实现原理"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/归一化操作/LayerNormGrad.md","filePath":"api/SIMD-API/高阶API/归一化操作/LayerNormGrad.md"}'),r={name:"api/SIMD-API/高阶API/归一化操作/LayerNormGrad.md"};function l(i,a,o,d,c,m){return s(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="layernormgrad" tabindex="-1">LayerNormGrad <a class="header-anchor" href="#layernormgrad" aria-label="Permalink to &quot;LayerNormGrad&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>LayerNormGrad是一个函数，用于计算LayerNorm的反向传播梯度。该接口单独使用会输出x、resForGamma；也可以和LayerNormGradBeta配合使用，输出的resForGamma传递给LayerNormGradBeta， LayerNormGradBeta接口会输出gamma和beta，配合使用时就可以同时得到x、Gamma、beta。</p><p>算法公式为:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pd_xl(BSH) = data_dy * data_gamma</span></span>
<span class="line"><span>pd_var(H) = np.sum(((-0.5) * pd_xl * (data_x - data_mean) * np.power((data_variance + EPSILON), (-1.5))), reduce_axis, keepdims=True)</span></span>
<span class="line"><span>pd_mean(BS1) = np.sum(((-1.0) * pd_xl * np.power((data_variance + EPSILON), (-0.5))), reduce_axis, keepdims=True) + pd_var * (1.0 / H) * np.sum(((-2.0) * (data_x - data_mean)), reduce_axis, keepdims=True)</span></span>
<span class="line"><span>pd_x(BSH) = pd_xl * np.power((data_variance + EPSILON), (-0.5)) + pd_var * (2.0 / H) * (data_x - data_mean) + pd_mean * (1.0 / H)</span></span>
<span class="line"><span>res_for_gamma(BSH) = (data_x - data_mean) * np.power((data_variance + EPSILON), (-0.5))</span></span></code></pre></div><h2 id="实现原理" tabindex="-1">实现原理 <a class="header-anchor" href="#实现原理" aria-label="Permalink to &quot;实现原理&quot;">​</a></h2><p>以float类型，ND格式，输入为inputDy[B, S, H], inputX[B, S, H], inputVariance[B, S], inputMean[B, S], inputGamma[H]为例，描述LayerNormGrad高阶API内部算法框图，如下图所示。</p><p><strong>图 1</strong> LayerNormGrad算法框图<br><img src="`+p+`" alt="" title="LayerNormGrad算法框图"></p><p>计算过程分为如下几步，均在Vector上进行：</p><ol><li>ComputePdX1步骤：计算inputDy*inputGamma，结果存储至x1Tensor；</li><li>ComputePdX2步骤：inputMean先通过Brcb将shape扩充到[B, S, H]，再计算inputX-inputMean，结果存储至x2Tensor；</li><li>ComputePdVar步骤：实现公式np.sum(((-0.5) * x1Tensor * x2Tensor * np.power((inputVariance + EPSILON), (-1.5))))的计算，power方法的实现通过Sqrt, Div, Mul三条基础API组合实现，结果存储至pdVarTensor；</li><li>ComputePdMean：实现公式np.sum(((-1.0) * x1Tensor * np.power((inputVariance + EPSILON), (-0.5)))) + pd_var * (1.0 / H) * np.sum(((-2.0) * (x2Tensor)))的计算，power方法通过Sqrt, Div两条基础API组合实现，结果存储至pdMeanTensor。同时，利用中间计算结果，根据公式x2Tensor * np.power((inputVariance + EPSILON), (-0.5))，计算出resForGamma的结果；</li><li>ComputePdX步骤：实现公式x1Tensor * np.power((inputVariance + EPSILON), (-0.5)) + pd_var*(2.0 / H)*(x2Tensor) + pd_mean*(1.0 / H)的计算，结果存入outputPdX。</li></ol><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><p>由于该接口的内部实现中涉及复杂的计算，需要额外的临时空间来存储计算过程中的中间变量。临时空间大小BufferSize的获取方法：通过<a href="./LayerNormGrad-Tiling.html">LayerNormGrad Tiling</a>中提供的GetLayerNormGradMaxMinTmpSize接口获取所需最大和最小临时空间大小，最小空间可以保证功能正确，最大空间用于提升性能。</p><p>临时空间支持<strong>接口框架申请</strong>和开发者<strong>通过sharedTmpBuffer入参传入</strong>两种方式，因此LayerNormGrad接口的函数原型有两种：</p><ul><li><p>通过sharedTmpBuffer入参传入临时空间</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, bool isReuseSource = false&gt;</span></span>
<span class="line"><span>__aicore__ inline void LayerNormGrad(const LocalTensor&lt;T&gt;&amp; outputPdX, const LocalTensor&lt;T&gt;&amp; resForGamma, const LocalTensor&lt;T&gt;&amp; inputDy, const LocalTensor&lt;T&gt;&amp; inputX, const LocalTensor&lt;T&gt;&amp; inputVariance, const LocalTensor&lt;T&gt;&amp; inputMean, const LocalTensor&lt;T&gt;&amp; inputGamma, LocalTensor&lt;uint8_t&gt;&amp; sharedTmpBuffer, T epsilon, LayerNormGradTiling &amp;tiling, const LayerNormGradShapeInfo&amp; shapeInfo = {})</span></span></code></pre></div><p>该方式下开发者需自行申请并管理临时内存空间，并在接口调用完成后，复用该部分内存，内存不会反复申请释放，灵活性较高，内存利用率也较高。</p></li><li><p>接口框架申请临时空间</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, bool isReuseSource = false&gt;</span></span>
<span class="line"><span>__aicore__ inline void LayerNormGrad(const LocalTensor&lt;T&gt;&amp; outputPdX, const LocalTensor&lt;T&gt;&amp; resForGamma, const LocalTensor&lt;T&gt;&amp; inputDy, const LocalTensor&lt;T&gt;&amp; inputX, const LocalTensor&lt;T&gt;&amp; inputVariance, const LocalTensor&lt;T&gt;&amp; inputMean, const LocalTensor&lt;T&gt;&amp; inputGamma, T epsilon, LayerNormGradTiling&amp; tiling, const LayerNormGradShapeInfo&amp; shapeInfo = {})</span></span></code></pre></div><p>该方式下开发者无需申请，但是需要预留临时空间的大小。</p></li></ul><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>操作数的数据类型。支持的数据类型为：half、float。</td></tr><tr><td>isReuseSource</td><td>是否允许修改源操作数，默认值为false。如果开发者允许源操作数被改写，可以使能该参数，使能后能够节省部分内存空间。 设置为true，则本接口内部计算时复用inputX的内存空间，节省内存空间；设置为false，则本接口内部计算时不复用inputX的内存空间。 对于float数据类型输入支持开启该参数，half数据类型输入不支持开启该参数。 isReuseSource的使用样例请参考更多样例。</td></tr></tbody></table><p><strong>表 2</strong> 接口参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>outputPdX</td><td>输出</td><td>目的操作数，shape为[B, S, H]，LocalTensor数据结构的定义请参考LocalTensor。尾轴长度需要32B对齐。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。</td></tr><tr><td>resForGamma</td><td>输出</td><td>目的操作数，shape为[B, S, H]，LocalTensor数据结构的定义请参考LocalTensor。尾轴长度需要32B对齐。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。</td></tr><tr><td>inputDy</td><td>输入</td><td>源操作数，shape为[B, S, H]，LocalTensor数据结构的定义请参考LocalTensor。inputDy的数据类型需要与目的操作数保持一致，尾轴长度需要32B对齐。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。</td></tr><tr><td>inputX</td><td>输入</td><td>源操作数，shape为[B, S, H]，LocalTensor数据结构的定义请参考LocalTensor。inputX的数据类型需要与目的操作数保持一致，尾轴长度需要32B对齐。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。</td></tr><tr><td>inputVariance</td><td>输入</td><td>方差，shape为[B, S]，LocalTensor数据结构的定义请参考LocalTensor。inputVariance的数据类型需要与目的操作数保持一致，尾轴长度需要32B对齐。需提前调用LayerNorm接口获取方差。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。</td></tr><tr><td>inputMean</td><td>输入</td><td>均值，shape为[B, S]，LocalTensor数据结构的定义请参考LocalTensor。inputMean的数据类型需要与目的操作数保持一致，尾轴长度需要32B对齐。需提前调用LayerNorm接口获取均值。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。</td></tr><tr><td>inputGamma</td><td>输入</td><td>源操作数，shape为[H]，LocalTensor数据结构的定义请参考LocalTensor。inputGamma的数据类型需要与目的操作数保持一致，尾轴长度需要32B对齐。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。</td></tr><tr><td>sharedTmpBuffer</td><td>输入</td><td>共享缓冲区，用于存放API内部计算产生的临时数据。该方式开发者可以自行管理sharedTmpBuffer内存空间，并在接口调用完成后，复用该部分内存，内存不会反复申请释放，灵活性较高，内存利用率也较高。共享缓冲区大小的获取方式请参考LayerNormGrad Tiling。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。</td></tr><tr><td>epsilon</td><td>输入</td><td>防除零的权重系数。</td></tr><tr><td>tiling</td><td>输入</td><td>LayerNormGrad计算所需Tiling信息。</td></tr><tr><td>shapeInfo</td><td>输入</td><td>表示LayerNormGrad各个输入的数据排布格式Format。默认值表示输入的Format为ND。支持的取值为DataFormat::ND。LayerNormGradShapeInfo类型，具体定义如下方代码所示。</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>struct LayerNormGradShapeInfo {</span></span>
<span class="line"><span>    DataFormat dataFormat = DataFormat::ND;</span></span>
<span class="line"><span>};</span></span></code></pre></div><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>操作数地址对齐要求请参见<a href="./../../通用说明和约束.html#section796754519912">通用地址对齐约束</a>。</li><li>源操作数和目的操作数的Tensor空间可以复用。</li><li>仅支持输入shape为ND格式。</li><li>输入数据不满足对齐要求时，开发者需要进行补齐，补齐的数据应设置为0，防止出现异常值从而影响网络计算。</li><li>不支持对尾轴H轴的切分。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>本样例中，输入inputX和inputDy的shape为[2, 32, 16]，inputVariance和inputMean的shape为[2, 32]，inputGamma的shape为[16]。输出outputPdX和resForGamma的shape为[2, 32, 16]。数据排布均为ND格式，数据类型均为float，不复用源操作数的内存空间。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// outputPdX: 输出对输入 X 的梯度，即 dX，shape 为 [B, S, H]</span></span>
<span class="line"><span>// resForGamma: 输出用于计算 gamma 和 beta 梯度的中间结果（如 dy * normalized_x），shape 为 [B, S, H]</span></span>
<span class="line"><span>// inputDy: 输入的上层梯度 dy，shape 为 [B, S, H]</span></span>
<span class="line"><span>// inputX: 前向传播时的输入 X，shape 为 [B, S, H]</span></span>
<span class="line"><span>// inputVariance: 前向 LayerNorm 计算得到的方差 variance，shape 为 [B, S]</span></span>
<span class="line"><span>// inputMean: 前向 LayerNorm 计算得到的均值 mean，shape 为 [B, S]</span></span>
<span class="line"><span>// inputGamma: LayerNorm 中的缩放参数 gamma，shape 为 [H]</span></span>
<span class="line"><span>// sharedTmpBuffer: 开发者管理的临时缓冲区，用于存放内部计算中的中间变量</span></span>
<span class="line"><span>// epsilon: 防除零小量，例如 1e-5</span></span>
<span class="line"><span>// tiling: 包含计算所需 Tiling 信息的结构体（如 block、thread 等划分）</span></span>
<span class="line"><span>// shapeInfo: 可选参数，描述输入张量的数据排布格式，当前仅支持 ND 格式</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 使用 LayerNormGrad 接口执行 Layer Normalization 的反向传播计算：</span></span>
<span class="line"><span>AscendC::LayerNormGrad&lt;float, isReuseSource&gt;(</span></span>
<span class="line"><span>    outputPdX,        // 输出：输入梯度 dX，shape [B, S, H]</span></span>
<span class="line"><span>    resForGamma,      // 输出：中间结果，用于计算 dgamma/dbeta</span></span>
<span class="line"><span>    inputDy,          // 输入：上层梯度 dy，shape [B, S, H]</span></span>
<span class="line"><span>    inputX,           // 输入：原始输入 X，shape [B, S, H]</span></span>
<span class="line"><span>    inputVariance,    // 输入：前向计算的方差 variance，shape [B, S]</span></span>
<span class="line"><span>    inputMean,        // 输入：前向计算的均值 mean，shape [B, S]</span></span>
<span class="line"><span>    inputGamma,       // 输入：缩放参数 gamma，shape [H]</span></span>
<span class="line"><span>    sharedTmpBuffer,  // 输入：开发者提供的临时空间（需通过 GetLayerNormGradMaxMinTmpSize 获取大小）</span></span>
<span class="line"><span>    epsilon,          // 输入：防除零系数ε</span></span>
<span class="line"><span>    tiling,           // 输入：Tiling 信息，由 Tiling 工具生成</span></span>
<span class="line"><span>    {DataFormat::ND}  // 输入：shapeInfo，默认为 DataFormat::ND</span></span>
<span class="line"><span>);</span></span></code></pre></div><p>示例结果如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入数据(inputDy, shape:[1, 8, 8]): </span></span>
<span class="line"><span>[  0.  1.  2.  3.  4.  5.  6.  7.</span></span>
<span class="line"><span>   8.  9. 10. 11. 12. 13. 14. 15.</span></span>
<span class="line"><span>  16. 17. 18. 19. 20. 21. 22. 23.</span></span>
<span class="line"><span>  24. 25. 26. 27. 28. 29. 30. 31.</span></span>
<span class="line"><span>  32. 33. 34. 35. 36. 37. 38. 39.</span></span>
<span class="line"><span>  40. 41. 42. 43. 44. 45. 46. 47.</span></span>
<span class="line"><span>  48. 49. 50. 51. 52. 53. 54. 55.</span></span>
<span class="line"><span>  56. 57. 58. 59. 60. 61. 62. 63. ]</span></span>
<span class="line"><span>输入数据(inputX, shape:[1, 8, 8]): </span></span>
<span class="line"><span>[  0.  1.  2.  3.  4.  5.  6.  7.</span></span>
<span class="line"><span>   8.  9. 10. 11. 12. 13. 14. 15.</span></span>
<span class="line"><span>  16. 17. 18. 19. 20. 21. 22. 23.</span></span>
<span class="line"><span>  24. 25. 26. 27. 28. 29. 30. 31.</span></span>
<span class="line"><span>  32. 33. 34. 35. 36. 37. 38. 39.</span></span>
<span class="line"><span>  40. 41. 42. 43. 44. 45. 46. 47.</span></span>
<span class="line"><span>  48. 49. 50. 51. 52. 53. 54. 55.</span></span>
<span class="line"><span>  56. 57. 58. 59. 60. 61. 62. 63. ]</span></span>
<span class="line"><span>输入数据(inputMean, shape:[8]): </span></span>
<span class="line"><span>[ 3.5 11.5 19.5 27.5 35.5 43.5 51.5 59.5 ]</span></span>
<span class="line"><span>输入数据(inputVariance, shape:[8]): </span></span>
<span class="line"><span>[ 5.25 5.25 5.25 5.25 5.25 5.25 5.25 5.25 ]</span></span>
<span class="line"><span>输入数据(inputGamma, shape:[8]): </span></span>
<span class="line"><span>[ 0. 1. 2. 3. 4. 5. 6. 7. ]</span></span>
<span class="line"><span>输出数据(outputPdX): </span></span>
<span class="line"><span>[ 3.0548172 0.4362857 -1.3093826 -2.182187 -2.1821284 -1.309207 0.4365778 3.0552254 3.0545845 0.4361186 -1.3094826 -2.1822214 -2.1820965 -1.3091087 0.4367447 3.055458 3.0543518 0.4359522 -1.3095818 -2.1822548 -2.182064 -1.3090096 0.43690872 3.055687 3.054119 0.43578815 -1.309679 -2.1822853 -2.182026 -1.3089066 0.437088 3.0559235 3.0538864 0.43562222 -1.3097801 -2.1823158 -2.1819916 -1.3088074 0.43724823 3.05616 3.0536423 0.4354477 -1.3098869 -2.1823578 -2.181961 -1.3087158 0.43740845 3.0563965 3.0534134 0.43528175 -1.3099861 -2.1823883 -2.1819305 -1.308609 0.43756104 3.0566254 3.0531921 0.43511963 -1.3100777 -2.1824188 -2.1818848 -1.3085022 0.43774414 3.0568542 ]</span></span>
<span class="line"><span>输出数据(resForGamma): </span></span>
<span class="line"><span>[ -1.5275106 -1.091079 -0.6546474 -0.21821581 0.21821581 0.6546474 1.091079 1.5275106 -1.5275106 -1.091079 -0.6546474 -0.21821581 0.21821581 0.6546474 1.091079 1.5275106 -1.5275106 -1.091079 -0.6546474 -0.21821581 0.21821581 0.6546474 1.091079 1.5275106 -1.5275106 -1.091079 -0.6546474 -0.21821581 0.21821581 0.6546474 1.091079 1.5275106 -1.5275106 -1.091079 -0.6546474 -0.21821581 0.21821581 0.6546474 1.091079 1.5275106 -1.5275106 -1.091079 -0.6546474 -0.21821581 0.21821581 0.6546474 1.091079 1.5275106 -1.5275106 -1.091079 -0.6546474 -0.21821581 0.21821581 0.6546474 1.091079 1.5275106 -1.5275106 -1.091079 -0.6546474 -0.21821581 0.21821581 0.6546474 1.091079 1.5275106 ]</span></span></code></pre></div>`,31)])])}const T=n(r,[["render",l]]);export{h as __pageData,T as default};
